    tokens: list of strings, each token is an integer or one of '+', '-', '*', '/'.
    Returns the integer result. Division truncates toward zero.
    """
    stack = []
    for token in tokens:
        if token in '+-*/':
            b = stack.pop()
            a = stack.pop()
            if token == '+':
                stack.append(a + b)
            elif token == '-':
                stack.append(a - b)
            elif token == '*':
                stack.append(a * b)
            else:  # token == '/'
                # int() truncates toward zero in Python
                stack.append(int(a / b))
        else:
            stack.append(int(token))
    return stack[0]

