def solve(a, b):
    """Return the Levenshtein distance between two strings.
    Handles None inputs by treating them as empty strings and ensures a
    and b are strings. Uses O(min(len(a), len(b))) space.
    """
    # Normalize inputs
    if a is None:
        a = ''
    if b is None:
        b = ''
    a = str(a)
    b = str(b)
    # Quick shortcuts
    if a == b:
        return 0
    # If one is empty
    if not a:
        return len(b)
    if not b:
        return len(a)
    # If one is a prefix of the other, distance is length difference
    if a.startswith(b):
        return len(a) - len(b)
    if b.startswith(a):
        return len(b) - len(a)
    n, m = len(a), len(b)
    # Ensure that b is the shorter string to use less memory
    if m > n:
        a, b = b, a
        n, m = m, n
    # Initialize previous row of DP table
    prev = list(range(m + 1))
    for i in range(1, n + 1):
        cur = [i] + [0] * m
        ai = a[i - 1]
        for j in range(1, m + 1):
            cost = 0 if ai == b[j - 1] else 1
            # deletion, insertion, substitution
            cur[j] = min(prev[j] + 1, cur[j - 1] + 1, prev[j - 1] + cost)
        prev = cur
    return prev[m]

