    """Levenshtein distance supporting strings, bytes, or any iterable.
    Returns the minimum number of single-element insertions, deletions or
    substitutions required to transform *a* into *b*.
    """
    # Normalize None to empty sequence
    if a is None:
        a = []
    if b is None:
        b = []
    # Convert to list of elements (works for strings, bytes, lists, tuples, etc.)
    if isinstance(a, (str, bytes, bytearray)):
        seq_a = list(a)
    else:
        try:
            seq_a = list(a)
        except TypeError:
            # fallback to string representation
            seq_a = list(str(a))
    if isinstance(b, (str, bytes, bytearray)):
        seq_b = list(b)
    else:
        try:
            seq_b = list(b)
        except TypeError:
            seq_b = list(str(b))
    # Quick shortcuts
    if seq_a == seq_b:
        return 0
    n, m = len(seq_a), len(seq_b)
    if n == 0:
        return m
    if m == 0:
        return n
    # Ensure seq_b is the shorter one for space efficiency
    if m > n:
        seq_a, seq_b = seq_b, seq_a
        n, m = m, n
    # DP: previous row
    prev = list(range(m + 1))
    for i in range(1, n + 1):
        cur = [i] + [0] * m
        ai = seq_a[i - 1]
        for j in range(1, m + 1):
            cost = 0 if ai == seq_b[j - 1] else 1
            cur[j] = min(prev[j] + 1,      # deletion
                         cur[j - 1] + 1,  # insertion
                         prev[j - 1] + cost)  # substitution
        prev = cur
    return prev[m]

