def solve(tokens):
    """Evaluate an RPN expression.
    Tokens may be strings or numbers. Division truncates toward zero.
    Empty tokens are ignored.
    """
    stack = []
    ops = {'+', '-', '*', '/'}
    for token in tokens:
        # Normalize token to string for operator check
        if token == '' or token is None:
            continue
        if isinstance(token, str) and token in ops:
            b = stack.pop()
            a = stack.pop()
            if token == '+':
                stack.append(a + b)
            elif token == '-':
                stack.append(a - b)
            elif token == '*':
                stack.append(a * b)
            else:  # '/'
                # Truncate toward zero
                stack.append(int(a / b))
        else:
            # Operand: convert to int (supports int, str, etc.)
            stack.append(int(token))
    return stack[0] if stack else 0

