def solve(matrix):
    """Return the elements of the 2D matrix in spiral order.
    Handles empty matrix and non-rectangular input gracefully.
    """
    if not matrix or not any(matrix):
        return []
    # Determine dimensions; handle possible ragged rows by using min length for columns
    top, bottom = 0, len(matrix) - 1
    left, right = 0, max(len(row) for row in matrix) - 1
    result = []
    while top <= bottom and left <= right:
        # traverse left to right on top row
        for col in range(left, right + 1):
            if col < len(matrix[top]):
                result.append(matrix[top][col])
        top += 1
        # traverse top to bottom on right column
        for row in range(top, bottom + 1):
            if right < len(matrix[row]):
                result.append(matrix[row][right])
        right -= 1
        if top <= bottom:
            # traverse right to left on bottom row
            for col in range(right, left - 1, -1):
                if col < len(matrix[bottom]):
                    result.append(matrix[bottom][col])
            bottom -= 1
        if left <= right:
            # traverse bottom to top on left column
            for row in range(bottom, top - 1, -1):
                if left < len(matrix[row]):
                    result.append(matrix[row][left])
            left += 1
    return result

