def solve(s):
    """Balanced brackets checker tolerant of various input types.

    *s* may be a string, None, or an iterable containing bracket characters.
    Non‑bracket characters are ignored. Returns True if the brackets are
    balanced and properly nested, otherwise False.
    """
    if s is None:
        return True
    # Extract a sequence of bracket characters to process
    if isinstance(s, str):
        seq = s
    else:
        try:
            # Assume iterable of characters or strings
            seq = ''.join(ch for ch in s if isinstance(ch, str) and ch in '()[]{}')
        except Exception:
            # Fallback: convert whole object to string and use that
            seq = str(s)
    pairs = {')': '(', ']': '[', '}': '{'}
    opening = set(pairs.values())
    stack = []
    for ch in seq:
        if ch in opening:
            stack.append(ch)
        elif ch in pairs:
            if not stack or stack[-1] != pairs[ch]:
                return False
            stack.pop()
    return not stack
